// Bloc du 09/11 (4) : R2, horizons bornés par le verrou drand (calls 4 j, pronostics).
(() => {
  const add = {"Échéance trop lointaine : {d} jours au plus.":["Deadline too far away: {d} days at most.","截止时间太远：最多 {d} 天。","Срок слишком далёкий: не более {d} дней.","Vade çok uzak: en fazla {d} gün.","Hạn quá xa: tối đa {d} ngày.","Tenggat terlalu jauh: paling lama {d} hari.","마감이 너무 멉니다: 최대 {d}일.","Prazo muito distante: no máximo {d} dias."],"Échéance trop lointaine ou absente : vérifiez la date.":["Deadline too far away or missing: check the date.","截止时间太远或缺失：请检查日期。","Срок слишком далёкий или не указан: проверьте дату.","Vade çok uzak veya eksik: tarihi kontrol edin.","Hạn quá xa hoặc bị thiếu: hãy kiểm tra ngày.","Tenggat terlalu jauh atau kosong: periksa tanggalnya.","마감이 너무 멀거나 없습니다: 날짜를 확인하세요.","Prazo muito distante ou ausente: verifique a data."],"Réponses ouvertes à partir du {d}.":["Answers open from {d}.","自 {d} 起开放作答。","Ответы принимаются с {d}.","Yanıtlar {d} tarihinden itibaren açık.","Mở trả lời từ {d}.","Jawaban dibuka mulai {d}.","{d}부터 답변할 수 있습니다.","Respostas abertas a partir de {d}."],"Matchs les plus annoncés":["Most announced matches","最多预告的比赛","Самые анонсируемые матчи","En çok duyurulan maçlar","Trận đấu được công bố nhiều nhất","Pertandingan paling banyak diumumkan","가장 많이 예고된 경기","Jogos mais anunciados"],"Rendement moyen":["Average return","平均收益","Средняя доходность","Ortalama getiri","Lợi nhuận trung bình","Imbal hasil rata-rata","평균 수익률","Retorno médio"],"rendement moyen":["average return","平均收益","средняя доходность","ortalama getiri","lợi nhuận trung bình","imbal hasil rata-rata","평균 수익률","retorno médio"],"Aucun participant":["No participants","暂无参与者","Нет участников","Katılımcı yok","Chưa có người tham gia","Belum ada peserta","참가자 없음","Nenhum participante"],"Sapient ne répond pas : cliquez sur son icône pour le réveiller, puis réessayez.":["Sapient is not responding: click its icon to wake it up, then try again.","Sapient 没有响应：请点击其图标唤醒它，然后重试。","Sapient не отвечает: нажмите на его значок, чтобы разбудить, и повторите попытку.","Sapient yanıt vermiyor: uyandırmak için simgesine tıklayın, sonra yeniden deneyin.","Sapient không phản hồi: hãy nhấp vào biểu tượng của nó để đánh thức, rồi thử lại.","Sapient tidak merespons: klik ikonnya untuk membangunkannya, lalu coba lagi.","Sapient가 응답하지 않습니다. 아이콘을 클릭해 깨운 뒤 다시 시도하세요.","O Sapient não responde: clique no ícone para o reativar e tente de novo."],"Ouvrir ce call":["Open this call","开启此预测","Открыть этот колл","Bu call'u aç","Mở call này","Buka call ini","이 콜 열기","Abrir este call"],"Tout ouvrir ({n})":["Open all ({n})","全部开启（{n}）","Открыть все ({n})","Tümünü aç ({n})","Mở tất cả ({n})","Buka semua ({n})","모두 열기 ({n})","Abrir todos ({n})"],"{n} calls attendent leur ouverture.":["{n} calls are waiting to be opened.","{n} 个预测等待开启。","{n} коллов ждут открытия.","{n} call açılmayı bekliyor.","{n} call đang chờ được mở.","{n} call menunggu dibuka.","{n}개의 콜이 열리기를 기다리고 있습니다.","{n} calls aguardam abertura."],"Calls ouverts publiquement.":["Calls opened publicly.","预测已公开开启。","Коллы открыты публично.","Call'lar herkese açık olarak açıldı.","Các call đã được mở công khai.","Call dibuka secara publik.","콜이 공개적으로 열렸습니다.","Calls abertos publicamente."],"Call invalide : corrigez les champs en rouge.":["Invalid call: fix the fields in red.","预测无效：请修正红色字段。","Колл недействителен: исправьте поля, выделенные красным.","Geçersiz call: kırmızı alanları düzeltin.","Call không hợp lệ: hãy sửa các ô màu đỏ.","Call tidak valid: perbaiki kolom berwarna merah.","유효하지 않은 콜: 빨간색 항목을 수정하세요.","Call inválido: corrija os campos a vermelho."],"Au coup d'envoi":["At kickoff","开赛时","В момент начала матча","Maç başlangıcında","Khi trận đấu bắt đầu","Saat kickoff","경기 시작 시","No início do jogo"],"Match trop lointain : ce call pourra être scellé à partir du {d}.":["Match too far away: this call can be sealed from {d}.","比赛时间太远：此预测可从 {d} 起封存。","Матч слишком далеко: этот колл можно будет запечатать с {d}.","Maç çok uzak: bu call {d} tarihinden itibaren mühürlenebilir.","Trận đấu còn quá xa: có thể niêm phong call này từ {d}.","Pertandingan terlalu jauh: call ini dapat disegel mulai {d}.","경기가 너무 멉니다: 이 콜은 {d}부터 봉인할 수 있습니다.","Jogo demasiado distante: este call pode ser selado a partir de {d}."],"Finance / Politique":["Finance / Politics","金融 / 政治","Финансы / Политика","Finans / Siyaset","Tài chính / Chính trị","Keuangan / Politik","금융 / 정치","Finanças / Política"],"Libre":["Open topic","自由主题","Свободная тема","Serbest","Tự do","Bebas","자유 주제","Livre"],"Source officielle":["Official source","官方来源","Официальный источник","Resmî kaynak","Nguồn chính thức","Sumber resmi","공식 출처","Fonte oficial"],"Sujet public":["Public subject","公开主题","Публичная тема","Herkese açık konu","Chủ đề công khai","Subjek publik","공개 주제","Assunto público"],"Votre call, secret jusqu'à l'ouverture":["Your call, secret until it opens","您的预测，开启前保密","Ваш колл, секретный до открытия","Call'unuz, açılana kadar gizli","Call của bạn, bí mật đến khi mở","Call Anda, rahasia sampai dibuka","내 콜, 열릴 때까지 비공개","O seu call, secreto até abrir"],"Sans accents, 110 caractères au plus. Résultat non vérifié par le site, hors classement.":["No accents, 110 characters at most. Result not verified by the site, not ranked.","不含重音符号，最多 110 个字符。结果不经网站核实，不计入排名。","Без диакритики, не более 110 символов. Результат не проверяется сайтом и не идёт в рейтинг.","Aksansız, en fazla 110 karakter. Sonuç site tarafından doğrulanmaz, sıralamaya girmez.","Không dấu, tối đa 110 ký tự. Kết quả không được trang xác minh, không xếp hạng.","Tanpa aksen, maksimal 110 karakter. Hasil tidak diverifikasi situs, tidak masuk peringkat.","악센트 없이 최대 110자. 결과는 사이트가 검증하지 않으며 순위에 포함되지 않습니다.","Sem acentos, 110 caracteres no máximo. Resultado não verificado pelo site, fora do ranking."],"Résultat officiel, États-Unis":["Official result, United States","官方结果，美国","Официальный результат, США","Resmî sonuç, ABD","Kết quả chính thức, Hoa Kỳ","Hasil resmi, Amerika Serikat","공식 결과, 미국","Resultado oficial, Estados Unidos"],"Résultat officiel, France":["Official result, France","官方结果，法国","Официальный результат, Франция","Resmî sonuç, Fransa","Kết quả chính thức, Pháp","Hasil resmi, Prancis","공식 결과, 프랑스","Resultado oficial, França"],"Résultat officiel, Belgique":["Official result, Belgium","官方结果，比利时","Официальный результат, Бельгия","Resmî sonuç, Belçika","Kết quả chính thức, Bỉ","Hasil resmi, Belgia","공식 결과, 벨기에","Resultado oficial, Bélgica"],"Résultat officiel, Union européenne":["Official result, European Union","官方结果，欧盟","Официальный результат, Европейский союз","Resmî sonuç, Avrupa Birliği","Kết quả chính thức, Liên minh châu Âu","Hasil resmi, Uni Eropa","공식 결과, 유럽연합","Resultado oficial, União Europeia"],"Résultat officiel, Royaume-Uni":["Official result, United Kingdom","官方结果，英国","Официальный результат, Великобритания","Resmî sonuç, Birleşik Krallık","Kết quả chính thức, Vương quốc Anh","Hasil resmi, Britania Raya","공식 결과, 영국","Resultado oficial, Reino Unido"],"Source officielle inconnue : choisissez-en une dans la liste.":["Unknown official source: pick one from the list.","未知的官方来源：请从列表中选择。","Неизвестный официальный источник: выберите из списка.","Bilinmeyen resmî kaynak: listeden birini seçin.","Nguồn chính thức không xác định: hãy chọn trong danh sách.","Sumber resmi tidak dikenal: pilih dari daftar.","알 수 없는 공식 출처: 목록에서 선택하세요.","Fonte oficial desconhecida: escolha uma da lista."],"Pas de lien ni de contact dans un call libre.":["No link or contact in an open-topic call.","自由主题预测中不得包含链接或联系方式。","В свободном колле нельзя указывать ссылки и контакты.","Serbest call içinde bağlantı veya iletişim bilgisi olamaz.","Không được có liên kết hay thông tin liên hệ trong call tự do.","Tidak boleh ada tautan atau kontak dalam call bebas.","자유 주제 콜에는 링크나 연락처를 넣을 수 없습니다.","Sem links nem contactos num call livre."],"Un call libre se vend {n} TARI au plus : son résultat n’est pas vérifié par le site.":["An open-topic call sells for {n} TARI at most: its result is not verified by the site.","自由主题预测最多售价 {n} TARI：其结果不经网站核实。","Свободный колл продаётся не дороже {n} TARI: его результат не проверяется сайтом.","Serbest call en fazla {n} TARI’ye satılır: sonucu site tarafından doğrulanmaz.","Call tự do bán tối đa {n} TARI: kết quả không được trang xác minh.","Call bebas dijual maksimal {n} TARI: hasilnya tidak diverifikasi situs.","자유 주제 콜은 최대 {n} TARI에 판매됩니다: 결과는 사이트가 검증하지 않습니다.","Um call livre vende-se por {n} TARI no máximo: o resultado não é verificado pelo site."],"Call libre : son résultat n’est pas vérifié par le site et il ne compte pas au classement.":["Open-topic call: its result is not verified by the site and it does not count in the ranking.","自由主题预测：其结果不经网站核实，也不计入排名。","Свободный колл: его результат не проверяется сайтом и не учитывается в рейтинге.","Serbest call: sonucu site tarafından doğrulanmaz ve sıralamaya girmez.","Call tự do: kết quả không được trang xác minh và không tính vào xếp hạng.","Call bebas: hasilnya tidak diverifikasi situs dan tidak dihitung dalam peringkat.","자유 주제 콜: 결과는 사이트가 검증하지 않으며 순위에 반영되지 않습니다.","Call livre: o resultado não é verificado pelo site e não conta para o ranking."],"Le sujet, la date et la source officielle sont publics. Le choix reste scellé jusqu'à l'échéance, puis le résultat est tranché sur la publication officielle.":["The subject, the date and the official source are public. The choice stays sealed until the deadline, then the result is settled on the official publication.","主题、日期和官方来源是公开的。选择在到期前保持封存，之后依据官方公布判定结果。","Тема, дата и официальный источник публичны. Выбор остаётся запечатанным до срока, затем результат определяется по официальной публикации.","Konu, tarih ve resmî kaynak herkese açıktır. Seçim vadeye kadar mühürlü kalır, ardından sonuç resmî yayına göre belirlenir.","Chủ đề, ngày và nguồn chính thức là công khai. Lựa chọn được niêm phong đến hạn, sau đó kết quả được quyết định theo công bố chính thức.","Subjek, tanggal, dan sumber resmi bersifat publik. Pilihan tetap tersegel sampai jatuh tempo, lalu hasil diputuskan berdasarkan publikasi resmi.","주제, 날짜, 공식 출처는 공개됩니다. 선택은 만기까지 봉인되며, 이후 공식 발표에 따라 결과가 결정됩니다.","O assunto, a data e a fonte oficial são públicos. A escolha fica selada até ao prazo, depois o resultado é decidido pela publicação oficial."],"Le sujet est public, le texte reste scellé jusqu'à l'échéance. Un call libre prouve qu'il a été écrit avant : son résultat n'est pas vérifié par le site et il ne compte pas au classement.":["The subject is public, the text stays sealed until the deadline. An open-topic call proves it was written beforehand: its result is not verified by the site and it does not count in the ranking.","主题公开，文字在到期前保持封存。自由主题预测证明它是事先写下的：其结果不经网站核实，也不计入排名。","Тема публична, текст остаётся запечатанным до срока. Свободный колл доказывает, что он был написан заранее: его результат не проверяется сайтом и не учитывается в рейтинге.","Konu herkese açıktır, metin vadeye kadar mühürlü kalır. Serbest call önceden yazıldığını kanıtlar: sonucu site tarafından doğrulanmaz ve sıralamaya girmez.","Chủ đề công khai, nội dung được niêm phong đến hạn. Call tự do chứng minh nó được viết từ trước: kết quả không được trang xác minh và không tính vào xếp hạng.","Subjek bersifat publik, teks tetap tersegel sampai jatuh tempo. Call bebas membuktikan bahwa ia ditulis sebelumnya: hasilnya tidak diverifikasi situs dan tidak dihitung dalam peringkat.","주제는 공개되고 내용은 만기까지 봉인됩니다. 자유 주제 콜은 미리 작성되었음을 증명합니다: 결과는 사이트가 검증하지 않으며 순위에 반영되지 않습니다.","O assunto é público, o texto fica selado até ao prazo. Um call livre prova que foi escrito antes: o resultado não é verificado pelo site e não conta para o ranking."],"Texte secret":["Secret text","保密内容","Секретный текст","Gizli metin","Nội dung bí mật","Teks rahasia","비공개 내용","Texto secreto"],"Texte":["Text","内容","Текст","Metin","Nội dung","Teks","내용","Texto"],"Non vérifié":["Not verified","未核实","Не проверено","Doğrulanmadı","Chưa xác minh","Tidak diverifikasi","미검증","Não verificado"],"Résultat officiel attendu":["Official result pending","等待官方结果","Ожидается официальный результат","Resmî sonuç bekleniyor","Đang chờ kết quả chính thức","Menunggu hasil resmi","공식 결과 대기 중","Resultado oficial pendente"],"Résultat non vérifié par le site":["Result not verified by the site","结果未经网站核实","Результат не проверен сайтом","Sonuç site tarafından doğrulanmadı","Kết quả không được trang xác minh","Hasil tidak diverifikasi situs","사이트가 검증하지 않은 결과","Resultado não verificado pelo site"],"Annulé":["Cancelled","已取消","Отменён","İptal edildi","Đã hủy","Dibatalkan","취소됨","Cancelado"],"En attente":["Pending","待定","Ожидается","Bekliyor","Đang chờ","Menunggu","대기 중","Pendente"],"Résolution":["Resolution","结算依据","Расчёт","Sonuçlandırma","Cách xác định","Penyelesaian","판정 기준","Resolução"],"Soyez le premier à sceller":["Be the first to seal","成为第一个封存的人","Запечатайте первым","İlk mühürleyen siz olun","Hãy là người niêm phong đầu tiên","Jadilah yang pertama menyegel","첫 번째로 봉인해 보세요","Seja o primeiro a selar"],"Source":["Source","来源","Источник","Kaynak","Nguồn","Sumber","출처","Fonte"],"Règles : pas d’insulte, de racisme, de haine, de harcèlement, de contenu sexuel, de données personnelles, de lien ni d’arnaque. Un call crypto doit être cohérent avec le marché : entrée à moins de 10 % du prix, objectif et stop réalistes, échéance entre 1 h et 30 jours. Un call Finance / Politique nomme une source officielle de la liste, qui tranche son résultat. Un call libre se vend 10 TARI au plus et son résultat n’est pas vérifié. Ce qui enfreint ces règles est refusé ou masqué sur le site.":["Rules: no insults, racism, hate, harassment, sexual content, personal data, links or scams. A crypto call must be consistent with the market: entry within 10% of the price, realistic target and stop, deadline between 1 hour and 30 days. A Finance / Politics call names an official source from the list, which settles its result. An open-topic call sells for 10 TARI at most and its result is not verified. Anything that breaks these rules is refused or hidden on the site.","规则：禁止辱骂、种族歧视、仇恨、骚扰、色情内容、个人信息、链接和诈骗。加密货币预测必须与市场相符：入场价与现价相差不超过 10%，目标和止损合理，期限在 1 小时到 30 天之间。金融 / 政治预测须从列表中指定一个官方来源，由其判定结果。自由主题预测最多售价 10 TARI，其结果不经核实。违反规则的内容将被拒绝或在网站上隐藏。","Правила: без оскорблений, расизма, ненависти, травли, сексуального контента, персональных данных, ссылок и мошенничества. Крипто-колл должен соответствовать рынку: вход в пределах 10 % от цены, реалистичные цель и стоп, срок от 1 часа до 30 дней. Колл «Финансы / Политика» называет официальный источник из списка, по которому определяется результат. Свободный колл продаётся не дороже 10 TARI, его результат не проверяется. Всё, что нарушает правила, отклоняется или скрывается на сайте.","Kurallar: hakaret, ırkçılık, nefret, taciz, cinsel içerik, kişisel veri, bağlantı ve dolandırıcılık yok. Kripto call piyasayla tutarlı olmalıdır: giriş fiyatın en fazla %10 uzağında, gerçekçi hedef ve stop, vade 1 saat ile 30 gün arasında. Finans / Siyaset call’u listeden bir resmî kaynak belirtir; sonucu o kaynak belirler. Serbest call en fazla 10 TARI’ye satılır ve sonucu doğrulanmaz. Kuralları çiğneyen içerik reddedilir veya sitede gizlenir.","Quy tắc: không lăng mạ, phân biệt chủng tộc, thù ghét, quấy rối, nội dung tình dục, dữ liệu cá nhân, liên kết hay lừa đảo. Call crypto phải phù hợp với thị trường: giá vào cách giá hiện tại không quá 10%, mục tiêu và cắt lỗ thực tế, thời hạn từ 1 giờ đến 30 ngày. Call Tài chính / Chính trị nêu một nguồn chính thức trong danh sách, nguồn đó quyết định kết quả. Call tự do bán tối đa 10 TARI và kết quả không được xác minh. Nội dung vi phạm sẽ bị từ chối hoặc ẩn trên trang.","Aturan: tanpa hinaan, rasisme, kebencian, pelecehan, konten seksual, data pribadi, tautan, atau penipuan. Call kripto harus konsisten dengan pasar: entri dalam 10% dari harga, target dan stop realistis, tenggat antara 1 jam dan 30 hari. Call Keuangan / Politik menyebut sumber resmi dari daftar, yang menentukan hasilnya. Call bebas dijual maksimal 10 TARI dan hasilnya tidak diverifikasi. Yang melanggar aturan ditolak atau disembunyikan di situs.","규칙: 욕설, 인종차별, 혐오, 괴롭힘, 성적 콘텐츠, 개인정보, 링크, 사기는 금지됩니다. 암호화폐 콜은 시장과 일치해야 합니다: 진입가는 현재가의 10% 이내, 현실적인 목표와 손절, 만기는 1시간에서 30일 사이. 금융 / 정치 콜은 목록의 공식 출처를 지정하며 그 출처가 결과를 결정합니다. 자유 주제 콜은 최대 10 TARI에 판매되며 결과는 검증되지 않습니다. 규칙을 위반한 내용은 거부되거나 사이트에서 숨겨집니다.","Regras: sem insultos, racismo, ódio, assédio, conteúdo sexual, dados pessoais, links ou burlas. Um call cripto deve ser coerente com o mercado: entrada a menos de 10% do preço, alvo e stop realistas, prazo entre 1 hora e 30 dias. Um call Finanças / Política indica uma fonte oficial da lista, que decide o resultado. Um call livre vende-se por 10 TARI no máximo e o resultado não é verificado. O que infringe estas regras é recusado ou ocultado no site."],"Solde insuffisant : {a} disponibles, {b} nécessaires. Un call se paie avec des TARI publics, pas avec des TARI privés.":["Not enough balance: {a} available, {b} needed. A call is paid with public TARI, not private TARI.","余额不足：可用 {a}，需要 {b}。预测须用公开 TARI 支付，不能用隐私 TARI。","Недостаточно средств: доступно {a}, нужно {b}. Колл оплачивается публичными TARI, а не приватными.","Yetersiz bakiye: {a} mevcut, {b} gerekli. Call, gizli TARI ile değil açık TARI ile ödenir.","Không đủ số dư: có {a}, cần {b}. Call được trả bằng TARI công khai, không phải TARI riêng tư.","Saldo tidak cukup: tersedia {a}, dibutuhkan {b}. Call dibayar dengan TARI publik, bukan TARI privat.","잔액 부족: 보유 {a}, 필요 {b}. 콜은 비공개 TARI가 아닌 공개 TARI로 결제합니다.","Saldo insuficiente: {a} disponíveis, {b} necessários. Um call paga-se com TARI públicos, não com TARI privados."],"Plus de la moitié de la durée de ce call est écoulée : achat bloqué pour vous protéger.":["More than half of this call's duration has passed: purchase blocked to protect you.","该预测的时长已过半：为保护您，已阻止购买。","Прошло больше половины срока этого колла: покупка заблокирована ради вашей защиты.","Bu call'un süresinin yarısından fazlası geçti: sizi korumak için satın alma engellendi.","Đã qua hơn nửa thời hạn của call này: chặn mua để bảo vệ bạn.","Lebih dari separuh durasi call ini telah berlalu: pembelian diblokir untuk melindungi Anda.","이 콜의 기간이 절반 이상 지났습니다: 보호를 위해 구매가 차단됩니다.","Mais de metade da duração deste call já passou: compra bloqueada para o proteger."],"Ce call s'ouvre dans moins de 2 h : achat bloqué pour vous protéger.":["This call opens in less than 2 hours: purchase blocked to protect you.","该预测将在 2 小时内开启：为保护您，已阻止购买。","Этот колл откроется менее чем через 2 часа: покупка заблокирована ради вашей защиты.","Bu call 2 saatten kısa sürede açılacak: sizi korumak için satın alma engellendi.","Call này mở trong chưa đầy 2 giờ: chặn mua để bảo vệ bạn.","Call ini dibuka kurang dari 2 jam lagi: pembelian diblokir untuk melindungi Anda.","이 콜은 2시간 이내에 열립니다: 보호를 위해 구매가 차단됩니다.","Este call abre em menos de 2 horas: compra bloqueada para o proteger."],"Livré par le caller avant l'ouverture ; sinon remboursable depuis votre portfolio (bouton Rembourser).":["Delivered by the caller before it opens; otherwise refundable from your portfolio (Refund button).","由发布者在开启前交付；否则可在您的投资组合中退款（“退款”按钮）。","Колл доставляется автором до открытия; иначе его можно вернуть в портфеле (кнопка «Вернуть»).","Açılmadan önce caller tarafından teslim edilir; aksi halde portföyünüzden iade alınabilir (İade düğmesi).","Được caller giao trước khi mở; nếu không, có thể hoàn tiền từ danh mục của bạn (nút Hoàn tiền).","Dikirim oleh caller sebelum dibuka; jika tidak, dapat dikembalikan dari portofolio Anda (tombol Refund).","열리기 전에 콜러가 전달합니다. 전달되지 않으면 포트폴리오에서 환불할 수 있습니다(환불 버튼).","Entregue pelo caller antes de abrir; caso contrário, reembolsável no seu portfólio (botão Reembolsar)."],"Total de buts":["Total goals","总进球数","Тотал голов","Toplam gol","Tổng số bàn thắng","Total gol","총 골 수","Total de golos"],"Calls livrés à leurs acheteurs.":["Calls delivered to their buyers.","预测已交付给买家。","Коллы доставлены покупателям.","Call'lar alıcılarına teslim edildi.","Các call đã được giao cho người mua.","Call telah dikirim ke pembelinya.","콜이 구매자에게 전달되었습니다.","Calls entregues aos compradores."],"Activez la cloche d'un caller pour suivre ses calls ici.":["Turn on a caller's bell to follow their calls here.","开启某位发布者的铃铛，即可在此关注其预测。","Включите колокольчик автора, чтобы следить за его коллами здесь.","Bir caller'ın zilini açarak call'larını buradan takip edin.","Bật chuông của một caller để theo dõi các call của họ tại đây.","Aktifkan lonceng seorang caller untuk mengikuti call-nya di sini.","콜러의 알림 종을 켜면 여기에서 콜을 확인할 수 있습니다.","Ative o sino de um caller para seguir os calls dele aqui."],"a scellé un call {pair} : acheter":["sealed a {pair} call: buy","封存了一个 {pair} 预测：购买","запечатал колл {pair}: купить","bir {pair} call'u mühürledi: satın al","đã niêm phong một call {pair}: mua","menyegel call {pair}: beli","{pair} 콜을 봉인했습니다: 구매","selou um call {pair}: comprar"],"Aucun call jamais ouvert : tous ses calls ont été publiés à l'échéance.":["No call left unopened: all their calls were published at the deadline.","没有未开启的预测：其所有预测均在到期时公布。","Ни одного неоткрытого колла: все коллы опубликованы в срок.","Açılmamış call yok: tüm call'ları vadesinde yayımlandı.","Không có call nào bị bỏ ngỏ: mọi call đều được công bố đúng hạn.","Tidak ada call yang tak dibuka: semua call-nya dipublikasikan saat jatuh tempo.","열리지 않은 콜 없음: 모든 콜이 만기에 공개되었습니다.","Nenhum call por abrir: todos os calls foram publicados no prazo."],"Desk ouvert depuis plus d'un an : son historique ne peut pas être rajeuni.":["Desk open for more than a year: its history cannot be made younger.","Desk 已开设超过一年：其历史无法被改写得更新。","Деск открыт более года: его историю нельзя «омолодить».","Desk bir yıldan uzun süredir açık: geçmişi gençleştirilemez.","Desk đã mở hơn một năm: lịch sử của nó không thể làm mới lại.","Desk dibuka lebih dari setahun: riwayatnya tidak bisa dimudakan.","데스크가 1년 넘게 열려 있습니다: 이력은 되돌릴 수 없습니다.","Desk aberto há mais de um ano: o histórico não pode ser rejuvenescido."],"Annulé ou égalité":["Cancelled or tie","取消或平局","Отмена или ничья","İptal veya beraberlik","Hủy hoặc hòa","Dibatalkan atau seri","취소 또는 무승부","Cancelado ou empate"],"[contenu masqué]":["[content hidden]","[内容已隐藏]","[содержимое скрыто]","[içerik gizlendi]","[nội dung bị ẩn]","[konten disembunyikan]","[숨겨진 내용]","[conteúdo oculto]"],"Ce call contient un mot interdit par les règles.":["This call contains a word forbidden by the rules.","该预测包含规则禁止的词语。","Этот колл содержит слово, запрещённое правилами.","Bu call kuralların yasakladığı bir kelime içeriyor.","Call này chứa từ bị quy tắc cấm.","Call ini mengandung kata yang dilarang aturan.","이 콜에는 규칙상 금지된 단어가 포함되어 있습니다.","Este call contém uma palavra proibida pelas regras."],"Échéance trop proche : au moins 1 h.":["Deadline too close: at least 1 hour.","期限太近：至少 1 小时。","Срок слишком близко: не менее 1 часа.","Vade çok yakın: en az 1 saat.","Thời hạn quá gần: ít nhất 1 giờ.","Tenggat terlalu dekat: minimal 1 jam.","만기가 너무 가깝습니다: 최소 1시간.","Prazo demasiado próximo: pelo menos 1 hora."],"Ce type de pari ne peut pas être vérifié automatiquement : choisissez vainqueur, handicap ou total.":["This type of bet cannot be verified automatically: choose winner, spread or total.","此类投注无法自动核实：请选择胜者、让分或总分。","Такой тип ставки нельзя проверить автоматически: выберите победителя, фору или тотал.","Bu bahis türü otomatik doğrulanamaz: kazanan, handikap veya toplam seçin.","Loại cược này không thể xác minh tự động: hãy chọn đội thắng, chấp hoặc tổng.","Jenis taruhan ini tidak dapat diverifikasi otomatis: pilih pemenang, handicap, atau total.","이 유형의 베팅은 자동 검증할 수 없습니다: 승자, 핸디캡 또는 합계를 선택하세요.","Este tipo de aposta não pode ser verificado automaticamente: escolha vencedor, handicap ou total."],"Le match commence dans moins de 10 minutes ou a déjà commencé.":["The game starts in less than 10 minutes or has already started.","比赛将在 10 分钟内开始或已经开始。","Матч начнётся менее чем через 10 минут или уже начался.","Maç 10 dakikadan kısa sürede başlıyor veya çoktan başladı.","Trận đấu bắt đầu trong chưa đầy 10 phút hoặc đã bắt đầu.","Pertandingan dimulai kurang dari 10 menit lagi atau sudah dimulai.","경기가 10분 이내에 시작하거나 이미 시작했습니다.","O jogo começa em menos de 10 minutos ou já começou."],"Échéance trop lointaine : 30 jours au plus.":["Deadline too far away: 30 days at most.","期限太远：最多 30 天。","Срок слишком далеко: не более 30 дней.","Vade çok uzak: en fazla 30 gün.","Thời hạn quá xa: tối đa 30 ngày.","Tenggat terlalu jauh: maksimal 30 hari.","만기가 너무 멉니다: 최대 30일.","Prazo demasiado distante: 30 dias no máximo."],"Objectif trop proche de l’entrée (moins de 2 %).":["Target too close to the entry (less than 2%).","目标离入场价太近（不足 2%）。","Цель слишком близко к входу (менее 2 %).","Hedef girişe çok yakın (%2'den az).","Mục tiêu quá gần giá vào (dưới 2%).","Target terlalu dekat dengan entri (kurang dari 2%).","목표가 진입가에 너무 가깝습니다(2% 미만).","Alvo demasiado perto da entrada (menos de 2%)."],"Objectif irréaliste (plus de 50 % de l’entrée).":["Unrealistic target (more than 50% from the entry).","目标不现实（超过入场价的 50%）。","Нереалистичная цель (более 50 % от входа).","Gerçekçi olmayan hedef (girişin %50'sinden fazla).","Mục tiêu phi thực tế (hơn 50% so với giá vào).","Target tidak realistis (lebih dari 50% dari entri).","비현실적인 목표(진입가의 50% 초과).","Alvo irrealista (mais de 50% da entrada)."],"Stop trop proche de l’entrée (moins de 0,2 %).":["Stop too close to the entry (less than 0.2%).","止损离入场价太近（不足 0.2%）。","Стоп слишком близко к входу (менее 0,2 %).","Stop girişe çok yakın (%0,2'den az).","Cắt lỗ quá gần giá vào (dưới 0,2%).","Stop terlalu dekat dengan entri (kurang dari 0,2%).","손절이 진입가에 너무 가깝습니다(0.2% 미만).","Stop demasiado perto da entrada (menos de 0,2%)."],"Stop trop loin (plus de 30 % de l’entrée).":["Stop too far (more than 30% from the entry).","止损太远（超过入场价的 30%）。","Стоп слишком далеко (более 30 % от входа).","Stop çok uzak (girişin %30'undan fazla).","Cắt lỗ quá xa (hơn 30% so với giá vào).","Stop terlalu jauh (lebih dari 30% dari entri).","손절이 너무 멉니다(진입가의 30% 초과).","Stop demasiado longe (mais de 30% da entrada)."],"Objectif trop petit par rapport au stop (il doit valoir au moins la moitié du stop).":["Target too small compared with the stop (it must be at least half the stop).","目标相对止损过小（至少应为止损的一半）。","Цель слишком мала относительно стопа (она должна быть не меньше половины стопа).","Hedef stop'a göre çok küçük (stop'un en az yarısı olmalı).","Mục tiêu quá nhỏ so với cắt lỗ (phải bằng ít nhất một nửa mức cắt lỗ).","Target terlalu kecil dibanding stop (minimal setengah dari stop).","목표가 손절에 비해 너무 작습니다(손절의 절반 이상이어야 합니다).","Alvo demasiado pequeno face ao stop (deve valer pelo menos metade do stop)."],"Entrée trop éloignée du prix actuel (plus de 10 %).":["Entry too far from the current price (more than 10%).","入场价离现价太远（超过 10%）。","Вход слишком далеко от текущей цены (более 10 %).","Giriş güncel fiyattan çok uzak (%10'dan fazla).","Giá vào quá xa giá hiện tại (hơn 10%).","Entri terlalu jauh dari harga saat ini (lebih dari 10%).","진입가가 현재가에서 너무 멉니다(10% 초과).","Entrada demasiado longe do preço atual (mais de 10%)."],"Démonstration":["Demo","演示","Демо","Demo","Bản demo","Demo","데모","Demonstração"],"Desk de démonstration : ses calls ne sont plus livrés, achat désactivé.":["Demo desk: its calls are no longer delivered, purchase disabled.","演示 Desk：其预测不再交付，已停用购买。","Демо-деск: его коллы больше не доставляются, покупка отключена.","Demo desk: call'ları artık teslim edilmiyor, satın alma kapalı.","Desk demo: các call không còn được giao, đã tắt mua.","Desk demo: call-nya tidak lagi dikirim, pembelian dinonaktifkan.","데모 데스크: 콜이 더 이상 전달되지 않아 구매가 비활성화되었습니다.","Desk de demonstração: os calls já não são entregues, compra desativada."]};
  const L = ["en","zh","ru","tr","vi","id","ko","pt"];
  for (const [k, v] of Object.entries(add)) { if (window.SD_K.includes(k)) continue; window.SD_K.push(k); L.forEach((l, i) => window.SD_T[l].push(v[i])); }
})();

